"""ExamRadar FastAPI application."""
from __future__ import annotations

from contextlib import asynccontextmanager
from pathlib import Path

from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from fastapi.staticfiles import StaticFiles
from fastapi.responses import FileResponse

from .config import get_settings
from .seekdb import ensure_tables
from .routes import health, documents, search, coverage, usage


@asynccontextmanager
async def lifespan(app: FastAPI):
    ensure_tables()
    yield


app = FastAPI(title="ExamRadar", version="0.1.0", lifespan=lifespan)

s = get_settings()
app.add_middleware(
    CORSMiddleware,
    allow_origins=s.cors_origins_list,
    allow_methods=["*"],
    allow_headers=["*"],
)

app.include_router(health.router)
app.include_router(documents.router)
app.include_router(search.router)
app.include_router(coverage.router)
app.include_router(usage.router)

_static_dir = Path(__file__).resolve().parent.parent / "static"


@app.get("/")
def index():
    return FileResponse(_static_dir / "index.html")


@app.get("/import.html")
def import_page():
    return FileResponse(_static_dir / "import.html")


@app.get("/ask.html")
def ask_page():
    return FileResponse(_static_dir / "ask.html")


@app.get("/radar.html")
def radar_page():
    return FileResponse(_static_dir / "radar.html")


@app.get("/usage.html")
def usage_page():
    return FileResponse(_static_dir / "usage.html")


if _static_dir.is_dir():
    app.mount("/static", StaticFiles(directory=str(_static_dir)), name="static")

"""Embedding generation using fastembed (local) or OpenAI-compatible API."""
from __future__ import annotations

import json
from typing import Optional

import httpx

from .config import get_settings


class EmbeddingModel:
    def __init__(self):
        self._settings = get_settings()
        self._local_model = None

    def _get_local_model(self):
        if self._local_model is None:
            from fastembed import TextEmbedding
            self._local_model = TextEmbedding(self._settings.embedding_model)
        return self._local_model

    def embed(self, texts: list[str]) -> list[list[float]]:
        if self._settings.embedding_provider == "openai":
            return self._embed_openai(texts)
        return self._embed_local(texts)

    def embed_one(self, text: str, is_query: bool = False) -> list[float]:
        if is_query and self._settings.embedding_query_instruction:
            text = self._settings.embedding_query_instruction + text
        return self.embed([text])[0]

    def _embed_local(self, texts: list[str]) -> list[list[float]]:
        model = self._get_local_model()
        embeddings = list(model.embed(texts))
        return [e.tolist() for e in embeddings]

    def _embed_openai(self, texts: list[str]) -> list[list[float]]:
        s = self._settings
        if not s.embedding_base_url or not s.embedding_api_key:
            raise ValueError("OpenAI embedding requires EMBEDDING_BASE_URL and EMBEDDING_API_KEY")
        resp = httpx.post(
            f"{s.embedding_base_url}/embeddings",
            headers={"Authorization": f"Bearer {s.embedding_api_key}"},
            json={"model": s.embedding_model, "input": texts},
            timeout=60,
        )
        resp.raise_for_status()
        data = resp.json()
        return [item["embedding"] for item in sorted(data["data"], key=lambda x: x["index"])]


_model_instance: Optional[EmbeddingModel] = None


def get_embedding_model() -> EmbeddingModel:
    global _model_instance
    if _model_instance is None:
        _model_instance = EmbeddingModel()
    return _model_instance

"""Shared document ingestion pipeline: validate, chunk, embed, atomic import."""
from __future__ import annotations

import hashlib
from pathlib import Path

from .chunker import chunk_file, ChunkResult
from .embedding import get_embedding_model
from .seekdb import (
    find_document_by_sha256, import_document, insert_usage_event,
)

ALLOWED_DOC_KINDS = {"notes", "slides", "paper", "exam"}
ALLOWED_EXTENSIONS = {".md", ".txt", ".pdf"}
MAX_FILE_SIZE = 30 * 1024 * 1024  # 30 MB

_BATCH_SIZE = 16


class ValidationError(ValueError):
    pass


def validate_input(filename: str, doc_kind: str, content: bytes) -> None:
    if doc_kind not in ALLOWED_DOC_KINDS:
        raise ValidationError(f"doc_kind 只允许 {'/'.join(sorted(ALLOWED_DOC_KINDS))}，收到: {doc_kind}")
    ext = Path(filename or "").suffix.lower()
    if ext not in ALLOWED_EXTENSIONS:
        raise ValidationError(f"文件只支持 {'/'.join(sorted(ALLOWED_EXTENSIONS))}，收到: {filename}")
    if len(content) > MAX_FILE_SIZE:
        raise ValidationError(f"文件超过 30 MB 上限（{len(content)} 字节）")


def ingest_bytes(
    content: bytes,
    filename: str,
    course_id: str,
    doc_kind: str,
    source: str = "real",
) -> dict:
    """Ingest raw file content. Returns {document_id, chunk_count, skipped}.

    Everything (chunking, embedding) happens before any DB write; the DB
    write itself is a single transaction, so a failure never leaves a
    half-imported document behind.
    """
    validate_input(filename, doc_kind, content)
    sha = hashlib.sha256(content).hexdigest()

    existing = find_document_by_sha256(sha, course_id)
    if existing:
        return {
            "document_id": existing["id"],
            "chunk_count": existing["chunk_count"],
            "skipped": True,
            "message": "文件已存在（同课程内内容相同）",
        }

    suffix = Path(filename).suffix.lower()
    tmp = Path(f"/tmp/examradar_{sha}{suffix}")
    tmp.write_bytes(content)
    try:
        result: ChunkResult = chunk_file(str(tmp), doc_kind)
    finally:
        tmp.unlink(missing_ok=True)

    if not result.chunks:
        raise ValidationError("文件解析后没有可用内容")

    model = get_embedding_model()
    texts = [c.content for c in result.chunks]
    embeddings: list[list[float]] = []
    for i in range(0, len(texts), _BATCH_SIZE):
        embeddings.extend(model.embed(texts[i:i + _BATCH_SIZE]))

    rows = [
        {
            "content": c.content,
            "heading": c.heading,
            "page": c.page,
            "question_no": c.question_no,
            "points": c.points,
            "chunk_index": c.chunk_index,
            "embedding": emb,
        }
        for c, emb in zip(result.chunks, embeddings)
    ]

    file_type = result.file_type or suffix.lstrip(".")
    doc_id = import_document(course_id, filename, doc_kind, file_type, sha, rows)

    insert_usage_event(course_id, source, "import", {
        "document_id": doc_id, "doc_kind": doc_kind,
        "chunk_count": len(rows), "filename": filename,
    })
    return {
        "document_id": doc_id,
        "chunk_count": len(rows),
        "skipped": False,
    }

"""PowerContext client (minimal, for M1 health check only)."""
from __future__ import annotations

import httpx

from .config import get_settings


def check_powercontext() -> tuple[bool, str]:
    s = get_settings()
    try:
        resp = httpx.get(f"{s.powercontext_url}/health/ready", timeout=5)
        if resp.status_code == 200:
            return True, "ok"
        return False, f"status={resp.status_code}"
    except Exception as e:
        return False, str(e)

"""Document import endpoint."""
from __future__ import annotations

from typing import Optional

from fastapi import APIRouter, UploadFile, File, Form, Header, HTTPException

from ..ingest import ingest_bytes, ValidationError
from ..seekdb import get_documents

router = APIRouter()


@router.post("/api/documents")
def upload_document(
    file: UploadFile = File(...),
    course_id: str = Form(...),
    doc_kind: str = Form(...),
    x_examradar_source: Optional[str] = Header(None),
):
    # Sync def: chunking + embedding run in the threadpool, so the event
    # loop (and every other request) is not blocked during import.
    source = "auto" if x_examradar_source == "auto" else "real"
    content = file.file.read()

    try:
        return ingest_bytes(content, file.filename or "unknown", course_id,
                            doc_kind, source)
    except ValidationError as e:
        raise HTTPException(status_code=400, detail=str(e))


@router.get("/api/documents")
def list_documents(course_id: str):
    return get_documents(course_id)

"""Coverage analysis API endpoints."""
from __future__ import annotations

from typing import Optional

from fastapi import APIRouter, Header, HTTPException, Query
from pydantic import BaseModel

from ..coverage import analyze, get_latest

router = APIRouter()


class AnalyzeRequest(BaseModel):
    course_id: str
    syllabus_text: str


@router.post("/api/coverage/analyze")
def coverage_analyze(req: AnalyzeRequest,
                     x_examradar_source: Optional[str] = Header(None)):
    source = "auto" if x_examradar_source == "auto" else "real"
    try:
        result = analyze(req.course_id, req.syllabus_text, source=source)
        return result
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))


@router.get("/api/coverage/latest")
def coverage_latest(course_id: str = Query(...)):
    result = get_latest(course_id)
    if result is None:
        raise HTTPException(status_code=404, detail="No coverage analysis found")
    return result

"""Unit tests for coverage judgment logic."""
from examradar.coverage import _compute_coverage_score, _judge_level, _normalize_kw


class TestNormalizeKw:
    def test_zero(self):
        assert _normalize_kw(0.0, 10.0) == 0.0

    def test_none(self):
        assert _normalize_kw(None, 10.0) == 0.0

    def test_half_scale(self):
        assert _normalize_kw(5.0, 10.0) == 0.5

    def test_at_scale(self):
        assert _normalize_kw(10.0, 10.0) == 1.0

    def test_above_scale_capped(self):
        assert _normalize_kw(20.0, 10.0) == 1.0


class TestComputeCoverageScore:
    def test_both_zero(self):
        score = _compute_coverage_score(0.0, 0.0, 10.0)
        assert score == 0.0

    def test_semantic_only(self):
        score = _compute_coverage_score(1.0, 0.0, 10.0)
        assert abs(score - 0.6) < 0.001

    def test_keyword_only(self):
        score = _compute_coverage_score(0.0, 10.0, 10.0)
        assert abs(score - 0.4) < 0.001

    def test_both_high(self):
        score = _compute_coverage_score(0.8, 10.0, 10.0)
        assert abs(score - (0.6 * 0.8 + 0.4 * 1.0)) < 0.001

    def test_none_scores(self):
        score = _compute_coverage_score(None, None, 10.0)
        assert score == 0.0


class TestJudgeLevel:
    def test_covered(self):
        assert _judge_level(0.60) == "covered"

    def test_thin(self):
        assert _judge_level(0.30) == "thin"

    def test_missing(self):
        assert _judge_level(0.10) == "missing"

    def test_boundary_covered(self):
        assert _judge_level(0.55) == "covered"

    def test_boundary_thin(self):
        assert _judge_level(0.20) == "thin"

    def test_just_below_covered(self):
        assert _judge_level(0.54) == "thin"

    def test_just_below_thin(self):
        assert _judge_level(0.19) == "missing"

"""Unit tests for text cleaning (cleaner.py)."""
from examradar.cleaner import (
    clean_extracted_text, normalize_text, validate_cjk_chars, is_mostly_cjk,
    strip_footer_page_number,
)


class TestNormalizeText:
    def test_kangxi_radical_to_standard(self):
        kangxi_ri = "\u2f47"  # Kangxi radical for 日
        result = normalize_text(kangxi_ri)
        assert result == "日"
        assert ord(result) == 0x65E5

    def test_radical_supplement_to_standard(self):
        # ⻚ U+2EDA (CJK Radicals Supplement) -> 页
        assert normalize_text("\u2eda") == "页"

    def test_standard_cjk_unchanged(self):
        text = "数据库系统原理"
        assert normalize_text(text) == text

    def test_mixed_text(self):
        text = "⽇志记录与⽇志文件"  # Kangxi radicals mixed with standard chars
        result = normalize_text(text)
        assert "日志" in result
        assert "\u2f47" not in result

    def test_fullwidth_punctuation_preserved(self):
        # No full-text NFKC: full-width punctuation must stay full-width.
        text = "先写日志原则（WAL）：第7讲"
        assert normalize_text(text) == text

    def test_ascii_unchanged(self):
        text = "(5 分) B+树: 第7讲"
        assert normalize_text(text) == text


class TestCleanExtractedText:
    def test_remove_spaces_between_chinese(self):
        text = "数据 库 系统 原理"
        result = clean_extracted_text(text)
        assert "数据库系统原理" in result

    def test_preserve_english_spaces(self):
        text = "hello world"
        result = clean_extracted_text(text)
        assert result == "hello world"

    def test_collapse_blank_lines(self):
        text = "line1\n\n\n\nline2"
        result = clean_extracted_text(text)
        assert result == "line1\n\nline2"

    def test_strip_whitespace(self):
        text = "  hello  \n  world  "
        result = clean_extracted_text(text)
        assert result.startswith("hello")
        assert result.endswith("world")

    def test_kangxi_normalization_in_context(self):
        text = "⽇志先写原则"
        result = clean_extracted_text(text)
        assert "日志先写原则" in result

    def test_newline_between_chinese_preserved(self):
        # A newline between two CJK chars is a real line break (e.g. title
        # followed by body on the next line) and must NOT be removed.
        text = "日志记录与日志文件\n日志按时间顺序追加写入"
        result = clean_extracted_text(text)
        assert "日志文件\n日志按" in result

    def test_cjk_space_across_newline_not_joined(self):
        text = "标题有尾随空格 \n正文开头"
        result = clean_extracted_text(text)
        assert result == "标题有尾随空格\n正文开头"

    def test_mixed_chinese_english(self):
        text = "B+树 的 范围 查询"
        result = clean_extracted_text(text)
        assert "B+树" in result

    def test_fullwidth_punctuation_preserved(self):
        text = "1.（5 分）设有关系学生 S(Sno, Sname)。"
        result = clean_extracted_text(text)
        assert "（5 分）" in result
        assert "。" in result

    def test_crlf_normalized(self):
        text = "第一行\r\n第二行"
        result = clean_extracted_text(text)
        assert result == "第一行\n第二行"

    def test_ideographic_space_between_cjk_removed(self):
        text = "满分：100 分　　闭卷"
        result = clean_extracted_text(text)
        assert result == "满分：100 分闭卷"


class TestStripFooterPageNumber:
    def test_strips_trailing_digit_line(self):
        assert strip_footer_page_number("标题\n正文内容\n12") == "标题\n正文内容"

    def test_keeps_digit_in_body(self):
        assert strip_footer_page_number("第12页\n正文") == "第12页\n正文"

    def test_keeps_plain_text(self):
        assert strip_footer_page_number("只有正文") == "只有正文"

    def test_no_leading_blank_line_left(self):
        assert strip_footer_page_number("标题\n正文\n3") == "标题\n正文"


class TestValidateCjkChars:
    def test_clean_text(self):
        suspicious = validate_cjk_chars("数据库系统")
        assert len(suspicious) == 0

    def test_kangxi_detected(self):
        suspicious = validate_cjk_chars("⽇志")
        assert len(suspicious) > 0

    def test_after_normalize_clean(self):
        text = normalize_text("⽇志")
        suspicious = validate_cjk_chars(text)
        assert len(suspicious) == 0


class TestIsMostlyCjk:
    def test_chinese_text(self):
        assert is_mostly_cjk("数据库系统原理") is True

    def test_english_text(self):
        assert is_mostly_cjk("hello world") is False

    def test_empty(self):
        assert is_mostly_cjk("") is False

    def test_mixed(self):
        assert is_mostly_cjk("B+树索引") is True

"""Unit tests for ingest validation (no DB access needed — validation
runs before any DB call)."""
import pytest

from examradar.ingest import validate_input, ValidationError, MAX_FILE_SIZE


def test_valid_kind_and_extension():
    validate_input("note.md", "notes", b"x")


def test_invalid_kind():
    with pytest.raises(ValidationError, match="doc_kind"):
        validate_input("note.md", "syllabus", b"x")


def test_invalid_extension():
    with pytest.raises(ValidationError, match="文件只支持"):
        validate_input("photo.jpg", "notes", b"x")


def test_no_extension():
    with pytest.raises(ValidationError):
        validate_input("README", "notes", b"x")


def test_file_too_large():
    with pytest.raises(ValidationError, match="30 MB"):
        validate_input("big.md", "notes", b"x" * (MAX_FILE_SIZE + 1))


def test_boundary_size_ok():
    validate_input("big.md", "notes", b"x" * 1024)


def test_all_allowed_kinds():
    for kind in ("notes", "slides", "paper", "exam"):
        validate_input("f.md", kind, b"x")

