41	<label for="file-input">选择文件</label>
42	<input type="file" id="file-input" accept=".md,.txt,.pdf" required style="margin-top:4px">
43	<button type="submit" class="btn" style="margin-top:16px" id="upload-btn">上传并导入</button>
44	</form>
45	<div id="upload-status"></div>
46	</div>
47	<div class="card">
48	<h2>已导入资料</h2>
49	<button class="btn" onclick="loadDocs()">刷新列表</button>
50	<div id="doc-list" style="margin-top:12px"></div>
51	</div>
52	</div>
53	<script>
54	function getSourceHeader() {
55	  const params = new URLSearchParams(window.location.search);
56	  return params.get('source') === 'auto' ? 'auto' : null;
57	}
58	
59	document.getElementById('upload-form').addEventListener('submit', async (e) => {
60	  e.preventDefault();
61	  const btn = document.getElementById('upload-btn');
62	  const status = document.getElementById('upload-status');
63	  btn.disabled = true;
64	  btn.textContent = '导入中...';
65	  status.innerHTML = '';
66	  const form = new FormData();
67	  form.append('file', document.getElementById('file-input').files[0]);
68	  form.append('course_id', document.getElementById('course-id').value);
69	  form.append('doc_kind', document.getElementById('doc-kind').value);
70	  try {
71	    const r = await fetch('/api/documents', { method: 'POST', body: form, headers: getSourceHeader() ? {'X-ExamRadar-Source': getSourceHeader()} : {} });
72	    const d = await r.json();
73	    if (!r.ok) {
74	      status.className = 'status err';
75	      status.textContent = '导入失败: ' + (d.detail || r.statusText);
76	    } else if (d.skipped) {
77	      status.className = 'status info';
78	      status.textContent = `文件已存在，跳过。已有 ${d.chunk_count} 个块。`;
79	    } else {
80	      status.className = 'status ok';
81	      status.textContent = `导入成功！共 ${d.chunk_count} 个块。`;
82	    }
83	    loadDocs();
84	  } catch(err) {
85	    status.className = 'status err';
86	    status.textContent = '导入失败: ' + err.message;
87	  }
88	  btn.disabled = false;
89	  btn.textContent = '上传并导入';
90	});
91	async function loadDocs() {
92	  const cid = document.getElementById('course-id').value;
93	  try {
94	    const r = await fetch(`/api/documents?course_id=${encodeURIComponent(cid)}`);
95	    const docs = await r.json();
96	    const el = document.getElementById('doc-list');
97	    if (!docs.length) { el.innerHTML = '<p style="color:#888">暂无资料</p>'; return; }
98	    el.innerHTML = `<table><tr><th>文件名</th><th>类型</th><th>块数</th></tr>` +
99	      docs.map(d => `<tr><td>${d.name}</td><td>${d.doc_kind}</td><td>${d.chunk_count}</td></tr>`).join('') +
100	      '</table>';
101	  } catch(e) {
102	    document.getElementById('doc-list').innerHTML = '<span style="color:red">加载失败</span>';
103	  }
104	}
105	loadDocs();
106	</script>
